DROP TABLE IF EXISTS `dc_collection_point`;

CREATE TABLE `dc_collection_point` (
  `point_id` bigint(20) NOT NULL COMMENT '采集点ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `point_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '采集点编码',
  `point_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '采集点名称',
  `point_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'MANUAL/AUTO',
  `equipment_id` bigint(20) DEFAULT NULL COMMENT '关联设备ID',
  `iot_device_id` bigint(20) DEFAULT NULL COMMENT '关联 IoT 设备 ID（AUTO 类型必填）',
  `iot_property_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IoT 属性编码（对应 iot_device_data.property_code）',
  `process_id` bigint(20) DEFAULT NULL COMMENT '关联工序ID',
  `data_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'NUMERIC/TEXT/ENUM',
  `unit` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `frequency` int(11) DEFAULT NULL COMMENT '采集频率(秒)',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVE' COMMENT 'ACTIVE/INACTIVE',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `last_archive_time` datetime DEFAULT NULL COMMENT '最后成功归档时间（数据补偿游标）',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`point_id`) USING BTREE,
  UNIQUE KEY `uk_point_code` (`tenant_id`,`point_code`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES数据采集点';

DROP TABLE IF EXISTS `dc_data_record`;

CREATE TABLE `dc_data_record` (
  `record_id` bigint(20) NOT NULL COMMENT '记录ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `point_id` bigint(20) NOT NULL COMMENT '采集点ID',
  `point_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '采集点编码(冗余)',
  `property_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IoT 属性编码（source=IoT 时填充）',
  `mes_wo_id` bigint(20) DEFAULT NULL COMMENT '关联MES工单ID',
  `card_id` bigint(20) DEFAULT NULL COMMENT '关联流转卡ID',
  `step_record_id` bigint(20) DEFAULT NULL COMMENT '关联工序记录ID',
  `numeric_value` decimal(14,4) DEFAULT NULL COMMENT '数值',
  `text_value` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文本值',
  `collect_time` datetime NOT NULL COMMENT '采集时间',
  `collect_by` bigint(20) DEFAULT NULL COMMENT '采集人(手动时)',
  `source` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'MANUAL' COMMENT 'MANUAL/IoT',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`record_id`) USING BTREE,
  UNIQUE KEY `uk_point_collect_time` (`tenant_id`,`point_id`,`collect_time`) USING BTREE,
  KEY `idx_point_id` (`point_id`) USING BTREE,
  KEY `idx_mes_wo_id` (`mes_wo_id`) USING BTREE,
  KEY `idx_collect_time` (`collect_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES采集数据记录';

DROP TABLE IF EXISTS `dhr_record`;

CREATE TABLE `dhr_record` (
  `dhr_id` bigint(20) NOT NULL COMMENT 'DHR主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `dhr_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'DHR编号',
  `work_order_id` bigint(20) DEFAULT NULL COMMENT 'MES工单ID(pro_work_order.mes_wo_id)',
  `work_order_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单编号(冗余快照)',
  `material_id` bigint(20) DEFAULT NULL COMMENT '产品物料ID',
  `material_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品物料编码(冗余快照)',
  `material_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品物料名称(冗余快照)',
  `lot_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批次号',
  `sn` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SN序列号',
  `planned_qty` decimal(14,4) DEFAULT NULL COMMENT '计划数量',
  `completed_qty` decimal(14,4) DEFAULT NULL COMMENT '完成数量',
  `scrap_qty` decimal(14,4) DEFAULT NULL COMMENT '报废数量',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'DRAFT' COMMENT '状态: DRAFT/SUBMITTED/RELEASED/REJECTED/ARCHIVED',
  `snapshot_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '快照总哈希(SM3)',
  `frozen_at` datetime DEFAULT NULL COMMENT '冻结时间(提交时写入)',
  `frozen_by` bigint(20) DEFAULT NULL COMMENT '冻结人',
  `submitted_at` datetime DEFAULT NULL COMMENT '提交时间',
  `submitted_by` bigint(20) DEFAULT NULL COMMENT '提交人',
  `submit_signature_id` bigint(20) DEFAULT NULL COMMENT '提交签名ID(es_signature, biz_type=DHR_SUBMIT)',
  `released_at` datetime DEFAULT NULL COMMENT '放行时间',
  `released_by` bigint(20) DEFAULT NULL COMMENT '放行人',
  `release_signature_id` bigint(20) DEFAULT NULL COMMENT '放行签名ID(biz_type=DHR_RELEASE)',
  `rejected_at` datetime DEFAULT NULL COMMENT '驳回时间',
  `rejected_by` bigint(20) DEFAULT NULL COMMENT '驳回人',
  `reject_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '驳回原因',
  `reject_signature_id` bigint(20) DEFAULT NULL COMMENT '驳回签名ID(biz_type=DHR_REJECT)',
  `archived_at` datetime DEFAULT NULL COMMENT '归档时间',
  `version` int(11) DEFAULT '1' COMMENT '版本号(每次状态流转+1)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志(0正常 1删除,仅DRAFT可删)',
  PRIMARY KEY (`dhr_id`) USING BTREE,
  UNIQUE KEY `uk_dhr_no` (`tenant_id`,`dhr_no`) USING BTREE,
  KEY `idx_dhr_wo` (`tenant_id`,`work_order_id`) USING BTREE,
  KEY `idx_dhr_status` (`tenant_id`,`status`) USING BTREE,
  KEY `idx_dhr_lot` (`tenant_id`,`lot_no`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='DHR批记录主表';

DROP TABLE IF EXISTS `dhr_section`;

CREATE TABLE `dhr_section` (
  `section_id` bigint(20) NOT NULL COMMENT '分册主键',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `dhr_id` bigint(20) NOT NULL COMMENT '所属DHR主表ID',
  `section_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分册编码(10个固定值)',
  `section_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分册名称',
  `item_count` int(11) DEFAULT '0' COMMENT '条目数(无数据时为0,分册仍落库)',
  `content_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '分册条目JSON',
  `content_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '正文哈希SM3(content_json)',
  `sort_order` int(11) DEFAULT '0' COMMENT '排序号(1基)',
  `create_time` datetime DEFAULT NULL COMMENT '写入时间',
  PRIMARY KEY (`section_id`) USING BTREE,
  UNIQUE KEY `uk_dhr_section` (`tenant_id`,`dhr_id`,`section_code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='DHR批记录分册(append-only)';

DROP TABLE IF EXISTS `eq_equipment`;

CREATE TABLE `eq_equipment` (
  `equipment_id` bigint(20) NOT NULL COMMENT '设备ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `equipment_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备编码',
  `equipment_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备名称',
  `equipment_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备类型',
  `model` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '型号',
  `manufacturer` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '制造商',
  `serial_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '出厂编号',
  `workcenter_id` bigint(20) DEFAULT NULL COMMENT '工作中心ID(ERP bd_workstation.workstation_id)',
  `workcenter_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工作中心编码(冗余)',
  `location` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '安装位置',
  `purchase_date` date DEFAULT NULL COMMENT '购置日期',
  `warranty_date` date DEFAULT NULL COMMENT '保修到期',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'NORMAL' COMMENT 'NORMAL/MAINTENANCE/FAULT/SCRAPPED',
  `inspection_items` json DEFAULT NULL COMMENT '点检项目及标准(JSON)',
  `last_inspection` json DEFAULT NULL COMMENT '最近一次点检结果(JSON)',
  `iot_device_id` bigint(20) DEFAULT NULL COMMENT '关联IoT设备ID(预留,无外键)',
  `planned_minutes_per_day` decimal(10,2) DEFAULT NULL COMMENT '计划生产时长(分钟/天), 供OEE聚合; 空则取 nexus.mes.eq.oee.planned-minutes-per-day(默认480)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`equipment_id`) USING BTREE,
  UNIQUE KEY `uk_equipment_code` (`tenant_id`,`equipment_code`) USING BTREE,
  UNIQUE KEY `uk_tenant_iot_device` (`tenant_id`,`iot_device_id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_workcenter_id` (`workcenter_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES设备台账';

