DROP TABLE IF EXISTS `eq_health_record`;

CREATE TABLE `eq_health_record` (
  `record_id` bigint(20) NOT NULL COMMENT '记录ID',
  `equipment_id` bigint(20) NOT NULL COMMENT '设备ID',
  `equipment_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备编码',
  `equipment_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备名称',
  `iot_device_id` bigint(20) DEFAULT NULL COMMENT 'IoT设备ID',
  `score` int(11) NOT NULL COMMENT '健康评分(0-100)',
  `grade` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '等级: HIGH(>=80)/MEDIUM(>=60)/LOW(<60)',
  `anomaly_points` int(11) DEFAULT '0' COMMENT '24h异常数据点数(z>3)',
  `repair_count_90d` int(11) DEFAULT '0' COMMENT '90天内维修单数',
  `open_repair_count` int(11) DEFAULT '0' COMMENT '未闭环维修单数',
  `detail_json` text COLLATE utf8mb4_unicode_ci COMMENT '明细JSON[{propertyCode,propertyName,mean,std,anomalyPoints}]',
  `prev_score` int(11) DEFAULT NULL COMMENT '前次评分(对比趋势)',
  `score_change` int(11) DEFAULT NULL COMMENT '评分变化(本次-前次)',
  `record_date` date NOT NULL COMMENT '评分日期',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000' COMMENT '租户ID',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`record_id`) USING BTREE,
  UNIQUE KEY `uk_tenant_eq_date` (`tenant_id`,`equipment_id`,`record_date`) USING BTREE,
  KEY `idx_ehr_equipment` (`equipment_id`) USING BTREE,
  KEY `idx_ehr_date` (`record_date`) USING BTREE,
  KEY `idx_ehr_tenant` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='设备健康评分记录表';

