DROP TABLE IF EXISTS `eq_inspection_record`;

CREATE TABLE `eq_inspection_record` (
  `record_id` bigint(20) NOT NULL COMMENT '记录ID',
  `tenant_id` varchar(20) DEFAULT '000000' COMMENT '租户ID',
  `equipment_id` bigint(20) NOT NULL COMMENT '设备ID',
  `station_code` varchar(64) DEFAULT NULL COMMENT '工位编码(工位终端提交时留痕)',
  `inspector_id` bigint(20) DEFAULT NULL COMMENT '点检人ID',
  `inspector_name` varchar(64) DEFAULT NULL COMMENT '点检人姓名',
  `operator_code` varchar(64) DEFAULT NULL COMMENT '点检人工号(设备通道免登录留痕)',
  `inspect_time` datetime NOT NULL COMMENT '点检时间',
  `results` text COMMENT '逐项点检明细 JSON: [{item,standard,actual,pass}]',
  `overall_pass` varchar(8) DEFAULT NULL COMMENT '总判定: Y合格/N不合格',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`record_id`) USING BTREE,
  KEY `idx_equipment_id` (`equipment_id`) USING BTREE,
  KEY `idx_inspect_time` (`inspect_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='设备点检记录(历史留痕, PC端与工位终端共用)';

DROP TABLE IF EXISTS `eq_maintenance_plan`;

CREATE TABLE `eq_maintenance_plan` (
  `plan_id` bigint(20) NOT NULL COMMENT '计划ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `plan_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '计划名称',
  `equipment_id` bigint(20) NOT NULL COMMENT '设备ID',
  `maintenance_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'DAILY/WEEKLY/MONTHLY/QUARTERLY/YEARLY',
  `cycle_days` int(11) DEFAULT NULL COMMENT '周期(天)',
  `next_date` date DEFAULT NULL COMMENT '下次保养日期(自动计算)',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '保养内容',
  `responsible_id` bigint(20) DEFAULT NULL COMMENT '负责人ID',
  `responsible_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '负责人姓名',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVE' COMMENT 'ACTIVE/INACTIVE',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`plan_id`) USING BTREE,
  KEY `idx_equipment_id` (`equipment_id`) USING BTREE,
  KEY `idx_next_date` (`next_date`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES设备保养计划';

DROP TABLE IF EXISTS `eq_maintenance_record`;

CREATE TABLE `eq_maintenance_record` (
  `record_id` bigint(20) NOT NULL COMMENT '记录ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `plan_id` bigint(20) DEFAULT NULL COMMENT '关联保养计划ID(可空)',
  `equipment_id` bigint(20) NOT NULL COMMENT '设备ID',
  `maintenance_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '保养类型(冗余)',
  `executor_id` bigint(20) DEFAULT NULL COMMENT '执行人ID',
  `executor_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '执行人姓名',
  `execute_time` datetime DEFAULT NULL COMMENT '执行时间',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '保养内容/执行情况',
  `result` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'NORMAL' COMMENT 'NORMAL/ABNORMAL',
  `duration_minutes` decimal(10,2) DEFAULT NULL COMMENT '保养占用时长(分钟), 供OEE的maintenance_minutes真实汇总',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  PRIMARY KEY (`record_id`) USING BTREE,
  KEY `idx_equipment_id` (`equipment_id`) USING BTREE,
  KEY `idx_plan_id` (`plan_id`) USING BTREE,
  KEY `idx_execute_time` (`execute_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES设备保养执行记录';

DROP TABLE IF EXISTS `eq_oee_record`;

CREATE TABLE `eq_oee_record` (
  `record_id` bigint(20) NOT NULL COMMENT '记录ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `equipment_id` bigint(20) NOT NULL COMMENT '设备ID',
  `equipment_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备编码(冗余)',
  `equipment_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备名称(冗余)',
  `equipment_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备类型(冗余)',
  `workcenter_id` bigint(20) DEFAULT NULL COMMENT '工作中心ID(冗余, 车间级聚合用)',
  `stat_date` date NOT NULL COMMENT '统计日期(日粒度)',
  `planned_minutes` decimal(10,2) DEFAULT '480.00' COMMENT '计划生产时长(分钟, 首版默认480=8h单班)',
  `downtime_minutes` decimal(10,2) DEFAULT '0.00' COMMENT '停机时长(分钟, 来自 eq_repair.downtime_hours 求和)',
  `maintenance_minutes` decimal(10,2) DEFAULT '0.00' COMMENT '保养占用时长(分钟, 预留, 首版0)',
  `run_minutes` decimal(10,2) DEFAULT '0.00' COMMENT '运行时长(分钟, = planned - downtime - maintenance)',
  `fault_count` int(11) DEFAULT '0' COMMENT '故障次数(eq_repair 当日报修数)',
  `availability` decimal(6,4) DEFAULT '0.0000' COMMENT '可用率/稼动率(0~1), = run/planned',
  `performance_rate` decimal(6,4) DEFAULT '1.0000' COMMENT '表现率(首版占位1.0, 待工单报工数据补全)',
  `quality_rate` decimal(6,4) DEFAULT '1.0000' COMMENT '质量率(首版占位1.0, 待质量数据补全)',
  `oee` decimal(6,4) DEFAULT '0.0000' COMMENT 'OEE = availability * performance * quality',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  PRIMARY KEY (`record_id`) USING BTREE,
  UNIQUE KEY `uk_tenant_eq_date` (`tenant_id`,`equipment_id`,`stat_date`) USING BTREE,
  KEY `idx_equipment_id` (`equipment_id`) USING BTREE,
  KEY `idx_stat_date` (`stat_date`) USING BTREE,
  KEY `idx_workcenter_id` (`workcenter_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES设备 OEE 聚合记录(日粒度)';

