DROP TABLE IF EXISTS `eq_patrol_record`;

CREATE TABLE `eq_patrol_record` (
  `record_id` bigint(20) NOT NULL COMMENT '记录ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `task_id` bigint(20) DEFAULT NULL COMMENT '关联任务ID(可空, 手动巡检无任务)',
  `route_id` bigint(20) DEFAULT NULL COMMENT '关联路线ID(冗余)',
  `equipment_id` bigint(20) NOT NULL COMMENT '设备ID',
  `equipment_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备编码(冗余)',
  `equipment_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备名称(冗余)',
  `check_item` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检查项目',
  `actual_value` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实际值/读数',
  `result` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'NORMAL' COMMENT 'NORMAL/ABNORMAL',
  `photo_oss_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '照片ossId',
  `executor_id` bigint(20) DEFAULT NULL COMMENT '执行人ID',
  `executor_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '执行人姓名',
  `execute_time` datetime DEFAULT NULL COMMENT '执行时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  PRIMARY KEY (`record_id`) USING BTREE,
  KEY `idx_task_id` (`task_id`) USING BTREE,
  KEY `idx_equipment_id` (`equipment_id`) USING BTREE,
  KEY `idx_execute_time` (`execute_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES巡检记录';

DROP TABLE IF EXISTS `eq_patrol_route`;

CREATE TABLE `eq_patrol_route` (
  `route_id` bigint(20) NOT NULL COMMENT '路线ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `route_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '路线名称',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '路线描述',
  `equipment_ids` text COLLATE utf8mb4_unicode_ci COMMENT '设备ID列表(JSON数组)',
  `check_items` text COLLATE utf8mb4_unicode_ci COMMENT '通用检查项(JSON数组)',
  `frequency` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'DAILY' COMMENT '频率 DAILY/WEEKLY/MONTHLY',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVE' COMMENT 'ACTIVE/INACTIVE',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  PRIMARY KEY (`route_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES巡检路线';

DROP TABLE IF EXISTS `eq_patrol_task`;

CREATE TABLE `eq_patrol_task` (
  `task_id` bigint(20) NOT NULL COMMENT '任务ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `route_id` bigint(20) NOT NULL COMMENT '关联路线ID',
  `route_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '路线名称(冗余)',
  `plan_date` date NOT NULL COMMENT '计划巡检日期',
  `actual_date` datetime DEFAULT NULL COMMENT '实际完成时间',
  `assigned_to_id` bigint(20) DEFAULT NULL COMMENT '指派人ID',
  `assigned_to_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '指派人姓名',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT 'PENDING/IN_PROGRESS/COMPLETED/CANCELLED',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  PRIMARY KEY (`task_id`) USING BTREE,
  KEY `idx_route_id` (`route_id`) USING BTREE,
  KEY `idx_plan_date` (`plan_date`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES巡检任务';

DROP TABLE IF EXISTS `eq_repair`;

CREATE TABLE `eq_repair` (
  `repair_id` bigint(20) NOT NULL COMMENT '维修ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `repair_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '维修单号',
  `equipment_id` bigint(20) NOT NULL COMMENT '设备ID',
  `fault_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '故障类型',
  `fault_desc` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '故障描述',
  `reporter_id` bigint(20) DEFAULT NULL COMMENT '报修人ID',
  `reporter_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '报修人姓名',
  `repairer_id` bigint(20) DEFAULT NULL COMMENT '维修人ID',
  `repairer_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '维修人姓名',
  `repair_start` datetime DEFAULT NULL COMMENT '维修开始时间',
  `repair_end` datetime DEFAULT NULL COMMENT '维修结束时间',
  `downtime_hours` decimal(10,2) DEFAULT NULL COMMENT '停机时长(小时)',
  `repair_cost` decimal(14,2) DEFAULT NULL COMMENT '维修成本',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'REPORTED' COMMENT 'REPORTED/REPAIRING/COMPLETED',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`repair_id`) USING BTREE,
  UNIQUE KEY `uk_repair_no` (`tenant_id`,`repair_no`) USING BTREE,
  KEY `idx_equipment_id` (`equipment_id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES设备维修记录';

