DROP TABLE IF EXISTS `eq_spare_erp_sync`;

CREATE TABLE `eq_spare_erp_sync` (
  `sync_id` bigint(20) NOT NULL COMMENT '同步台账ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `biz_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务幂等键 EQSP:<tenantId>:<logId>',
  `spare_id` bigint(20) NOT NULL COMMENT '备件ID',
  `spare_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备件编码(冗余)',
  `material_id` bigint(20) DEFAULT NULL COMMENT 'ERP物料ID',
  `warehouse_id` bigint(20) DEFAULT NULL COMMENT 'ERP仓库ID',
  `transaction_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'IN/OUT/REPAIR_USE/RETURN',
  `quantity` decimal(14,4) NOT NULL COMMENT '变动数量(正数)',
  `ref_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联单据类型',
  `ref_id` bigint(20) DEFAULT NULL COMMENT '关联单据ID',
  `log_id` bigint(20) DEFAULT NULL COMMENT 'MES库存流水ID(eq_spare_stock_log.log_id)',
  `sync_status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT 'PENDING/SENT/SYNCED/FAILED',
  `retry_count` int(11) DEFAULT '0' COMMENT '重投次数',
  `last_error` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近一次失败原因',
  `last_publish_time` datetime DEFAULT NULL COMMENT '最近一次投递时间',
  `erp_available_after` decimal(14,4) DEFAULT NULL COMMENT 'ERP过账后可用量快照',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  PRIMARY KEY (`sync_id`) USING BTREE,
  UNIQUE KEY `uk_tenant_biz_key` (`tenant_id`,`biz_key`) USING BTREE,
  KEY `idx_spare_id` (`spare_id`) USING BTREE,
  KEY `idx_sync_status` (`sync_status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES备件→ERP过账同步台账';

