DROP TABLE IF EXISTS `eq_spare_part`;

CREATE TABLE `eq_spare_part` (
  `spare_id` bigint(20) NOT NULL COMMENT '备件ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `spare_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '备件编码(唯一)',
  `spare_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '备件名称',
  `spec` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规格型号',
  `model` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '型号',
  `unit` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `category` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类(字典 mes_spare_category)',
  `safety_stock` decimal(14,4) DEFAULT '0.0000' COMMENT '安全库存',
  `current_stock` decimal(14,4) DEFAULT '0.0000' COMMENT '当前库存(ERP库存的派生冗余缓存; 权威账本在 wm_material_stock, 可用量=在库-已预留且frozen_flag=0)',
  `material_id` bigint(20) DEFAULT NULL COMMENT 'ERP物料ID(bd_material.material_id), NULL=未映射',
  `warehouse_id` bigint(20) DEFAULT NULL COMMENT 'ERP仓库ID(wm_warehouse.warehouse_id), 过账目标仓库',
  `unit_cost` decimal(18,4) DEFAULT '0.0000' COMMENT '备件参考单价(人工维护; 出入库过账时由服务端读库填入 MQ, 供 ERP 移动平均计价)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  PRIMARY KEY (`spare_id`) USING BTREE,
  UNIQUE KEY `uk_tenant_code` (`tenant_id`,`spare_code`) USING BTREE,
  KEY `idx_category` (`category`) USING BTREE,
  KEY `idx_material_id` (`material_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES备件主数据';

