DROP TABLE IF EXISTS `eq_spare_return`;

CREATE TABLE `eq_spare_return` (
  `return_id` bigint(20) NOT NULL COMMENT '退库单ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `return_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '退库单号 MESRT+yyyyMMdd+4位当日序号',
  `warehouse_id` bigint(20) DEFAULT NULL COMMENT '退库目标ERP仓库ID(wm_warehouse.warehouse_id)',
  `return_date` datetime DEFAULT NULL COMMENT '退库日期',
  `return_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'REPAIR_RETURN/EXCESS_RETURN/OTHER',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'DRAFT' COMMENT 'DRAFT/CONFIRMED/CANCELLED',
  `total_qty` decimal(14,4) DEFAULT '0.0000' COMMENT '明细数量合计',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `confirm_by` bigint(20) DEFAULT NULL COMMENT '确认人ID',
  `confirm_time` datetime DEFAULT NULL COMMENT '确认时间',
  `version` int(11) DEFAULT '0' COMMENT '版本号(确认时CAS自增)',
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  PRIMARY KEY (`return_id`) USING BTREE,
  UNIQUE KEY `uk_spare_return_no` (`tenant_id`,`return_no`) USING BTREE,
  KEY `idx_spare_return_status` (`tenant_id`,`status`) USING BTREE,
  KEY `idx_spare_return_date` (`tenant_id`,`return_date`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES备件退库单';

