DROP TABLE IF EXISTS `eq_spare_return_line`;

CREATE TABLE `eq_spare_return_line` (
  `line_id` bigint(20) NOT NULL COMMENT '明细行ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `return_id` bigint(20) NOT NULL COMMENT '退库单ID',
  `spare_id` bigint(20) NOT NULL COMMENT '备件ID',
  `spare_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备件编码(冗余)',
  `spare_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备件名称(冗余)',
