DROP TABLE IF EXISTS `eq_spare_stock_log`;

CREATE TABLE `eq_spare_stock_log` (
  `log_id` bigint(20) NOT NULL COMMENT '流水ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `spare_id` bigint(20) NOT NULL COMMENT '备件ID',
  `spare_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备件编码(冗余)',
  `spare_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备件名称(冗余)',
  `transaction_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'IN/OUT/REPAIR_USE',
  `quantity` decimal(14,4) NOT NULL COMMENT '变动数量(正数)',
  `before_qty` decimal(14,4) DEFAULT NULL COMMENT '变动前库存',
  `after_qty` decimal(14,4) DEFAULT NULL COMMENT '变动后库存',
  `ref_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联单据类型 MANUAL/REPAIR',
  `ref_id` bigint(20) DEFAULT NULL COMMENT '关联单据ID',
  `operator_id` bigint(20) DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人姓名',
  `operate_time` datetime DEFAULT NULL COMMENT '操作时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  PRIMARY KEY (`log_id`) USING BTREE,
  KEY `idx_spare_id` (`spare_id`) USING BTREE,
  KEY `idx_operate_time` (`operate_time`) USING BTREE,
  KEY `idx_ref` (`ref_type`,`ref_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES备件库存流水';

