DROP TABLE IF EXISTS `mes_flash_record`;

CREATE TABLE `mes_flash_record` (
  `flash_record_id` bigint(20) NOT NULL COMMENT '刷写记录ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `flash_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '刷写记录号(自动编码 MES_FLASH_NO)',
  `flash_type_id` bigint(20) DEFAULT NULL COMMENT '刷写类型ID(mes_flash_type)',
  `flash_type_code` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '刷写类型标识(快照: firmware_file/config_file/mac/sn)',
  `sn_id` bigint(20) NOT NULL COMMENT 'SN ID',
  `sn_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SN编码',
  `mes_wo_id` bigint(20) NOT NULL COMMENT 'MES工单ID',
  `wo_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单号',
  `card_id` bigint(20) DEFAULT NULL COMMENT '流转卡ID',
  `step_record_id` bigint(20) DEFAULT NULL COMMENT '流转卡工序记录ID(pro_flow_card_step)',
  `process_id` bigint(20) DEFAULT NULL COMMENT '工序ID',
  `process_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序编码',
  `process_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序名称',
  `content_ref_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '内容引用类型: FIRMWARE/CONFIG/MAC_POOL/SN_POOL/EXTERNAL',
  `content_ref_id` bigint(20) DEFAULT NULL COMMENT '内容源记录ID(固件=mes_firmware_id; 池类=工序配置的 contentRefId, 与完工门禁比对口径一致; 工序未配置时落本次分配的资源项ID)',
  `content_version` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '内容版本(固件类=固件版本)',
  `content_payload` text COLLATE utf8mb4_unicode_ci COMMENT '实际写入内容快照JSON(如 {"mac":"00:1A:2B:3C:4D:5E"})',
  `content_checksum` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '内容校验值(泛化MD5/校验码)',
  `equipment_id` bigint(20) DEFAULT NULL COMMENT '刷写设备ID(eq_equipment)',
  `equipment_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '刷写设备编码',
  `operator_id` bigint(20) DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人姓名',
  `flash_time` datetime DEFAULT NULL COMMENT '刷写时间',
  `result` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '结果: PASS/FAIL',
  `fail_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败原因',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '重试次数',
  `flash_mode` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL' COMMENT '刷写模式: AUTO/MANUAL',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志(0存在/2删除)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`flash_record_id`) USING BTREE,
  UNIQUE KEY `uk_tenant_flash_no` (`tenant_id`,`flash_no`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE,
  KEY `idx_sn` (`sn_id`) USING BTREE,
  KEY `idx_wo` (`mes_wo_id`) USING BTREE,
  KEY `idx_flash_type` (`tenant_id`,`flash_type_id`) USING BTREE,
  KEY `idx_content_ref` (`content_ref_type`,`content_ref_id`) USING BTREE,
  KEY `idx_sn_code` (`tenant_id`,`sn_code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='固件刷写记录(SN级)';

DROP TABLE IF EXISTS `mes_flash_type`;

CREATE TABLE `mes_flash_type` (
  `flash_type_id` bigint(20) NOT NULL COMMENT '刷写类型ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `type_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类型标识: firmware_file/config_file/mac/sn/external_*',
  `type_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '显示名',
  `source_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '内容来源: FILE/POOL/EXTERNAL/INLINE',
  `source_provider` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SPI Provider bean名(如 firmwareFileFlashProvider)',
  `source_config` text COLLATE utf8mb4_unicode_ci COMMENT '来源配置JSON(审批流标识/池ID/REST模板)',
  `verify_strategy` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MD5_MATCH' COMMENT '校验策略: MD5_MATCH/RESOURCE_BOUND/CUSTOM',
  `gate_enabled` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '是否参与完工门禁(0否/1是)',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ENABLED' COMMENT 'ENABLED/DISABLED',
  `sort_order` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志(0存在/2删除)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`flash_type_id`) USING BTREE,
  UNIQUE KEY `uk_tenant_type_code` (`tenant_id`,`type_code`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='刷写类型定义(配置化目录)';

DROP TABLE IF EXISTS `mes_label_print_log`;

CREATE TABLE `mes_label_print_log` (
  `log_id` bigint(20) NOT NULL COMMENT '打印日志ID',
  `tenant_id` varchar(20) DEFAULT '000000' COMMENT '租户ID',
  `sn_id` bigint(20) DEFAULT NULL COMMENT 'SN ID',
  `sn_code` varchar(64) DEFAULT NULL COMMENT 'SN编码',
  `template_id` bigint(20) DEFAULT NULL COMMENT '模板ID',
  `template_code` varchar(64) DEFAULT NULL COMMENT '模板编码(快照)',
  `printer_host` varchar(128) DEFAULT NULL COMMENT '打印机地址(快照)',
  `printer_port` int(11) DEFAULT '9100' COMMENT '打印机端口',
  `print_time` datetime DEFAULT NULL COMMENT '打印时间',
  `result` varchar(16) NOT NULL COMMENT '结果: SUCCESS/FAIL',
  `fail_reason` varchar(512) DEFAULT NULL COMMENT '失败原因',
  `retry_count` int(11) DEFAULT '0' COMMENT '重打计数(同SN同模板历史打印次数, 首次0)',
  `print_source` varchar(16) DEFAULT NULL COMMENT '来源: AUTO/REPRINT/TEST',
  `operator_id` bigint(20) DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(64) DEFAULT NULL COMMENT '操作人姓名',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`log_id`) USING BTREE,
  KEY `idx_label_print_sn_tpl` (`tenant_id`,`sn_id`,`template_id`,`result`) USING BTREE,
  KEY `idx_label_print_time` (`print_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='标签打印留痕';

DROP TABLE IF EXISTS `mes_label_template`;

CREATE TABLE `mes_label_template` (
  `template_id` bigint(20) NOT NULL COMMENT '模板ID',
  `tenant_id` varchar(20) DEFAULT '000000' COMMENT '租户ID',
  `template_code` varchar(64) NOT NULL COMMENT '模板编码',
  `template_name` varchar(128) NOT NULL COMMENT '模板名称',
  `label_type` varchar(20) DEFAULT 'SN' COMMENT '标签类型: SN 标签(流转卡标签后续扩展)',
  `label_lang` varchar(10) NOT NULL DEFAULT 'TSPL' COMMENT '打印机语言: TSPL/ZPL',
  `width_mm` int(11) DEFAULT '60' COMMENT '标签宽度(mm)',
  `height_mm` int(11) DEFAULT '40' COMMENT '标签高度(mm)',
  `printer_host` varchar(64) DEFAULT NULL COMMENT '网络打印机地址(TCP RAW 9100)',
  `printer_port` int(11) DEFAULT '9100' COMMENT '网络打印机端口',
  `content` text COMMENT '字段映射布局 JSON: {items:[{type,field,x,y,size,height}]}',
  `enabled` char(1) DEFAULT 'Y' COMMENT '是否启用(Y/N): SN 造码打印仅消费启用模板',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`template_id`) USING BTREE,
  UNIQUE KEY `uk_template_code` (`tenant_id`,`template_code`) USING BTREE,
  KEY `idx_label_type` (`label_type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='标签打印模板';

DROP TABLE IF EXISTS `mes_material_load`;

CREATE TABLE `mes_material_load` (
  `load_id` bigint(20) NOT NULL COMMENT '台账ID',
  `tenant_id` varchar(20) DEFAULT '000000' COMMENT '租户ID',
  `mes_wo_id` bigint(20) DEFAULT NULL COMMENT '工单ID(pro_work_order.mes_wo_id)',
  `wo_no` varchar(64) DEFAULT NULL COMMENT '工单编号',
  `station_code` varchar(64) NOT NULL COMMENT '工位编码',
  `process_code` varchar(64) DEFAULT NULL COMMENT '工序编码',
  `workstation_code` varchar(64) DEFAULT NULL COMMENT '工作中心编码(MBOM快照冗余)',
  `material_id` bigint(20) NOT NULL COMMENT '物料ID',
  `material_code` varchar(64) DEFAULT NULL COMMENT '物料编码',
  `material_name` varchar(128) DEFAULT NULL COMMENT '物料名称',
  `batch_id` bigint(20) DEFAULT NULL COMMENT '批次ID(wm_batch.batch_id)',
  `batch_code` varchar(64) DEFAULT NULL COMMENT '批次编码(wm_batch.batch_code)',
  `feeder_slot` varchar(32) DEFAULT NULL COMMENT '料站号(可空, 贴片机 feeder 位号等)',
  `is_alternative` char(1) DEFAULT 'N' COMMENT '是否替代料匹配: Y=bd_bom_alternative替代料, N=BOM主料',
  `operator_code` varchar(64) DEFAULT NULL COMMENT '上料人工号',
  `operator_name` varchar(64) DEFAULT NULL COMMENT '上料人姓名',
  `load_time` datetime NOT NULL COMMENT '上料时间',
  `status` varchar(16) DEFAULT 'ACTIVE' COMMENT '状态: ACTIVE=在机, REPLACED=已换料',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`load_id`) USING BTREE,
  KEY `idx_mes_wo_id` (`mes_wo_id`) USING BTREE,
  KEY `idx_station_code` (`station_code`) USING BTREE,
  KEY `idx_material` (`material_id`) USING BTREE,
  KEY `idx_load_time` (`load_time`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='工位物料上料台账(上料防错 C19 写入, 换料置 REPLACED)';

DROP TABLE IF EXISTS `mes_mbom`;

CREATE TABLE `mes_mbom` (
  `mbom_id` bigint(20) NOT NULL COMMENT 'MBOM ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `bom_id` bigint(20) NOT NULL COMMENT '关联ERP bd_bom.bom_id',
  `routing_id` bigint(20) DEFAULT NULL COMMENT '制造工艺路线ID(可继承自bd_bom.routing_id或MES侧指定)',
  `mbom_version` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MBOM版本号',
  `mbom_status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'DRAFT' COMMENT 'DRAFT/ACTIVE/FROZEN',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`mbom_id`) USING BTREE,
  UNIQUE KEY `uk_bom_id` (`tenant_id`,`bom_id`) USING BTREE,
  KEY `idx_routing_id` (`routing_id`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES制造BOM头';

