DROP TABLE IF EXISTS `mes_release_package`;

CREATE TABLE `mes_release_package` (
  `package_id` bigint(20) NOT NULL COMMENT '发布包ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `package_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发布包编码(自动编码 MES_RP_CODE)',
  `client_id` bigint(20) NOT NULL COMMENT '客户ID(bd_client.client_id)',
  `client_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户名称(冗余)',
  `material_id` bigint(20) NOT NULL COMMENT '成品物料ID(bd_material.material_id)',
  `material_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料编码(冗余)',
  `material_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料名称(冗余)',
  `customer_product_code` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户产品代号(客户对该产品的内部编号, 匹配键)',
  `customer_product_name` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户产品名称',
  `version` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '版本号(如 2.1)',
  `release_notes` text COLLATE utf8mb4_unicode_ci COMMENT '发布说明',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT '状态: DRAFT/IN_REVIEW/RELEASED/ARCHIVED',
  `effective_date` datetime DEFAULT NULL COMMENT '生效日期(空=发布即生效)',
  `expiry_date` datetime DEFAULT NULL COMMENT '过期日期(空=永久有效)',
  `is_default` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '是否客户+物料默认发布包(0否/1是, 客户+物料内唯一)',
  `select_flow_id` bigint(20) DEFAULT NULL COMMENT '审批流配置ID(wf_custom_form.id)',
  `published_by` bigint(20) DEFAULT NULL COMMENT '发布人ID',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志(0存在/2删除)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`package_id`) USING BTREE,
  UNIQUE KEY `uk_tenant_package_code` (`tenant_id`,`package_code`) USING BTREE,
  KEY `idx_client_material` (`client_id`,`material_id`) USING BTREE,
  KEY `idx_material` (`material_id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES客户定制化发布包主表';

DROP TABLE IF EXISTS `mes_release_pkg_bom_item`;

CREATE TABLE `mes_release_pkg_bom_item` (
  `item_id` bigint(20) NOT NULL COMMENT '主键ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `package_id` bigint(20) NOT NULL COMMENT '发布包ID(mes_release_package.package_id)',
  `action_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作类型: REPLACE/ADD/REMOVE',
  `child_material_id` bigint(20) DEFAULT NULL COMMENT '原物料ID(REPLACE/REMOVE 定位键, 按子件物料定位抗BOM版本变更)',
  `child_material_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原物料编码(冗余)',
  `child_material_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原物料名称(冗余)',
  `bom_detail_id` bigint(20) DEFAULT NULL COMMENT '标准BOM明细行ID(可选精确定位, 空则按原物料定位)',
  `target_material_id` bigint(20) DEFAULT NULL COMMENT '目标物料ID(REPLACE/ADD 必填)',
  `target_material_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标物料编码(冗余)',
  `target_material_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标物料名称(冗余)',
  `quantity_per_parent` decimal(18,6) DEFAULT NULL COMMENT '单位用量(空=REPLACE沿用原行/ADD必填)',
  `sort_order` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志(0存在/2删除)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`item_id`) USING BTREE,
  KEY `idx_package` (`package_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES发布包BOM选配表(替换/新增/移除)';

DROP TABLE IF EXISTS `mes_release_pkg_config`;

CREATE TABLE `mes_release_pkg_config` (
  `config_id` bigint(20) NOT NULL COMMENT '主键ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `package_id` bigint(20) NOT NULL COMMENT '发布包ID(mes_release_package.package_id)',
  `config_group` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置分组: FLASH/TEST_PARAM/LABEL/PACKAGING/PROCESS',
  `config_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置键',
  `config_value` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '配置值',
  `config_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'STRING' COMMENT '值类型: STRING/NUMBER/BOOLEAN/JSON',
  `process_id` bigint(20) DEFAULT NULL COMMENT '关联工序ID(空=全局生效)',
  `process_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序编码(冗余)',
  `sort_order` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志(0存在/2删除)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`config_id`) USING BTREE,
  KEY `idx_package` (`package_id`) USING BTREE,
  KEY `idx_group` (`config_group`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES发布包配置项表(测试参数/标签/包装/工艺参数)';

DROP TABLE IF EXISTS `mes_release_pkg_firmware`;

CREATE TABLE `mes_release_pkg_firmware` (
  `mapping_id` bigint(20) NOT NULL COMMENT '主键ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `package_id` bigint(20) NOT NULL COMMENT '发布包ID(mes_release_package.package_id)',
  `routing_step_id` bigint(20) DEFAULT NULL COMMENT '工艺路线步骤ID(bd_routing_step.step_id, 精确定位)',
  `process_id` bigint(20) DEFAULT NULL COMMENT '工序ID(bd_process.process_id, 宽泛定位)',
  `process_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序编码(冗余)',
  `process_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序名称(冗余)',
  `pcba_material_id` bigint(20) DEFAULT NULL COMMENT 'PCBA物料ID(固件物理载体, 追溯用, 可空)',
  `pcba_material_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'PCBA物料编码(冗余)',
  `pcba_material_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'PCBA物料名称(冗余)',
  `firmware_id` bigint(20) NOT NULL COMMENT '固件ID(mes_firmware.firmware_id, 仅RELEASED)',
  `firmware_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '固件编码(冗余)',
  `firmware_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '固件名称(冗余)',
  `firmware_version` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '固件版本(冗余)',
  `sort_order` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志(0存在/2删除)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`mapping_id`) USING BTREE,
  KEY `idx_package` (`package_id`) USING BTREE,
  KEY `idx_process` (`process_id`) USING BTREE,
  KEY `idx_firmware` (`firmware_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES发布包固件映射表(工序→固件)';

DROP TABLE IF EXISTS `mes_resource_item`;

CREATE TABLE `mes_resource_item` (
  `item_id` bigint(20) NOT NULL COMMENT '资源项ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `pool_id` bigint(20) NOT NULL COMMENT '资源池ID',
  `resource_value` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源值(如MAC 00:1A:2B:3C:4D:5E)',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AVAILABLE' COMMENT 'AVAILABLE/ALLOCATED/USED/SCRAPPED',
  `bound_sn_id` bigint(20) DEFAULT NULL COMMENT '已绑定SN ID(一SN绑一资源)',
  `bound_time` datetime DEFAULT NULL COMMENT '绑定时间',
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`item_id`) USING BTREE,
  UNIQUE KEY `uk_tenant_pool_value` (`tenant_id`,`pool_id`,`resource_value`) USING BTREE,
  KEY `idx_pool_status` (`pool_id`,`status`) USING BTREE,
  KEY `idx_bound_sn` (`bound_sn_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='资源池明细';

DROP TABLE IF EXISTS `mes_resource_pool`;

CREATE TABLE `mes_resource_pool` (
  `pool_id` bigint(20) NOT NULL COMMENT '资源池ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `pool_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源池编码(自动编码 MES_POOL_CODE)',
  `pool_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源池名称',
  `resource_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源类型: MAC/SN/CERT',
  `source` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INTERNAL' COMMENT '来源: INTERNAL(内部导入)/EXTERNAL(外部REST)',
  `external_config` text COLLATE utf8mb4_unicode_ci COMMENT '外部REST配置JSON(baseUrl/路径/鉴权, 经SSRF校验)',
  `alloc_strategy` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'FIFO' COMMENT '分配策略: FIFO/随机',
  `total_count` int(11) DEFAULT NULL COMMENT '总数量',
  `used_count` int(11) NOT NULL DEFAULT '0' COMMENT '已分配数量',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ENABLED' COMMENT 'ENABLED/DISABLED',
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`pool_id`) USING BTREE,
  UNIQUE KEY `uk_tenant_pool_code` (`tenant_id`,`pool_code`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE,
  KEY `idx_resource_type` (`resource_type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='刷写资源池(MAC/SN等)';

DROP TABLE IF EXISTS `mes_sn_bind_log`;

CREATE TABLE `mes_sn_bind_log` (
  `log_id` bigint(20) NOT NULL COMMENT '日志ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000',
  `action` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作: BIND/UNBIND/REBIND',
  `parent_sn_id` bigint(20) DEFAULT NULL COMMENT '父SN ID',
  `parent_sn_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '父SN编码',
  `component_sn_id` bigint(20) DEFAULT NULL COMMENT '组件SN ID',
  `component_sn_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '组件SN编码',
  `new_component_sn_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '换板新组件SN编码(REBIND)',
  `reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作原因(解绑/换板必填)',
  `operator_code` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作员工号',
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  PRIMARY KEY (`log_id`) USING BTREE,
  KEY `idx_parent` (`parent_sn_id`) USING BTREE,
  KEY `idx_component` (`component_sn_id`) USING BTREE,
  KEY `idx_parent_sn_code` (`tenant_id`,`parent_sn_code`) USING BTREE,
  KEY `idx_component_sn_code` (`tenant_id`,`component_sn_code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='关键件绑定操作日志';

DROP TABLE IF EXISTS `mes_station_device`;

CREATE TABLE `mes_station_device` (
  `device_id` bigint(20) NOT NULL COMMENT '设备ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000',
  `device_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备编码(工控机)',
  `station_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '绑定工位编码',
  `process_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '绑定工序编码',
  `app_version` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '终端版本',
  `operator_code` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前操作员工号',
  `operator_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前操作员姓名',
  `shutdown_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '主动下线标记: 1=应用正常退出(即时离线判定)',
  `last_heartbeat` datetime DEFAULT NULL COMMENT '最后心跳时间',
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  PRIMARY KEY (`device_id`) USING BTREE,
  UNIQUE KEY `uk_device_code` (`tenant_id`,`device_code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='工位终端设备台账';

