DROP TABLE IF EXISTS `mes_station_report`;

CREATE TABLE `mes_station_report` (
  `report_id` bigint(20) NOT NULL COMMENT '报工记录ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '000000',
  `report_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '报工类型: SINGLE(单件过站)/BATCH(批量计数)',
  `sn_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SN编码(SINGLE)',
  `station_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工位编码',
  `card_id` bigint(20) DEFAULT NULL COMMENT '流转卡ID',
  `step_record_id` bigint(20) DEFAULT NULL COMMENT '流转卡工序记录ID',
  `mes_wo_id` bigint(20) DEFAULT NULL COMMENT 'MES工单ID',
  `wo_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单编号(冗余)',
  `operator_id` bigint(20) DEFAULT NULL COMMENT '操作员用户ID',
  `operator_code` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作员工号',
  `operator_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作员姓名',
  `result` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结果: PASS/FAIL(SINGLE)',
  `defect_codes` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '不良代码(逗号分隔)',
  `good_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '良品数量',
  `defect_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '不良数量',
  `client_ts` bigint(20) NOT NULL COMMENT '客户端时间戳(毫秒)',
  `client_key` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '幂等键: SINGLE|sn|station|ts 或 BATCH|station|ts',
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  `request_fingerprint` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单件规范化原始请求SHA256指纹;旧记录不得猜测回填',
  PRIMARY KEY (`report_id`) USING BTREE,
  UNIQUE KEY `uk_tenant_client_key` (`tenant_id`,`client_key`) USING BTREE,
  KEY `idx_sn_code` (`sn_code`) USING BTREE,
  KEY `idx_station_code` (`station_code`) USING BTREE,
  KEY `idx_step_record` (`step_record_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='工位终端报工记录(设备通道)';

