DROP TABLE IF EXISTS `mes_test_record`;

CREATE TABLE `mes_test_record` (
  `test_record_id` bigint(20) NOT NULL COMMENT '测试记录ID',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `test_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '测试单号(一次SN测试一条单号, 共享多行)',
  `sn_id` bigint(20) NOT NULL COMMENT 'SN ID',
  `sn_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SN编码',
  `mes_wo_id` bigint(20) NOT NULL COMMENT 'MES工单ID',
  `wo_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单号',
  `card_id` bigint(20) DEFAULT NULL COMMENT '流转卡ID',
  `step_record_id` bigint(20) DEFAULT NULL COMMENT '流转卡工序记录ID(测试工序)',
  `process_id` bigint(20) DEFAULT NULL COMMENT '工序ID',
  `process_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序编码',
  `process_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序名称',
  `content_ref_id` bigint(20) DEFAULT NULL COMMENT '测试时内容源ID(固件类=mes_firmware_id)',
  `content_version` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '测试时内容版本',
  `test_item_id` bigint(20) NOT NULL COMMENT '测试项ID',
  `item_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '测试项编码(快照)',
  `item_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '测试项名称(快照)',
  `data_type` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '数据类型(快照)',
  `unit` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `numeric_value` decimal(18,4) DEFAULT NULL COMMENT '实测数值',
  `text_value` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实测文本',
  `upper_limit` decimal(18,4) DEFAULT NULL COMMENT '上限(快照)',
  `lower_limit` decimal(18,4) DEFAULT NULL COMMENT '下限(快照)',
  `target_value` decimal(18,4) DEFAULT NULL COMMENT '目标值(快照)',
  `pass_enum` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ENUM合格值(快照)',
  `result` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '结果: PASS/FAIL(空=未测)',
  `tester_id` bigint(20) DEFAULT NULL COMMENT '测试人ID',
  `tester_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '测试人姓名',
  `equipment_id` bigint(20) DEFAULT NULL COMMENT '测试设备ID',
  `equipment_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '测试设备编码',
  `test_time` datetime DEFAULT NULL COMMENT '测试时间',
  `test_mode` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL' COMMENT '测试模式: AUTO/MANUAL',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志(0存在/2删除)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`test_record_id`) USING BTREE,
  UNIQUE KEY `uk_tenant_test_no_item` (`tenant_id`,`test_no`,`test_item_id`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE,
  KEY `idx_sn` (`sn_id`) USING BTREE,
  KEY `idx_wo` (`mes_wo_id`) USING BTREE,
  KEY `idx_content_ref` (`content_ref_id`) USING BTREE,
  KEY `idx_sn_code` (`tenant_id`,`sn_code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='测试记录(SN级全检)';

DROP TABLE IF EXISTS `ncr_8d_report`;

CREATE TABLE `ncr_8d_report` (
  `report_id` bigint(20) NOT NULL COMMENT '报告ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `ncr_id` bigint(20) NOT NULL COMMENT '关联NCR ID',
  `d1_team` text COLLATE utf8mb4_unicode_ci COMMENT 'D1团队',
  `d2_problem` text COLLATE utf8mb4_unicode_ci COMMENT 'D2问题描述',
  `d3_interim` text COLLATE utf8mb4_unicode_ci COMMENT 'D3临时措施',
  `d4_root_cause` text COLLATE utf8mb4_unicode_ci COMMENT 'D4根因分析',
  `d5_permanent` text COLLATE utf8mb4_unicode_ci COMMENT 'D5永久措施',
  `d6_implement` text COLLATE utf8mb4_unicode_ci COMMENT 'D6措施实施与验证',
  `d7_prevent` text COLLATE utf8mb4_unicode_ci COMMENT 'D7预防措施',
  `d8_recognize` text COLLATE utf8mb4_unicode_ci COMMENT 'D8团队认可',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'DRAFT' COMMENT 'DRAFT/IN_PROGRESS/COMPLETED',
  `completed_by` bigint(20) DEFAULT NULL COMMENT '完成人',
  `completed_time` datetime DEFAULT NULL COMMENT '完成时间',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志(0正常 1删除)',
  PRIMARY KEY (`report_id`) USING BTREE,
  KEY `idx_ncr_id` (`ncr_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='8D报告';

