DROP TABLE IF EXISTS `ncr_order`;

CREATE TABLE `ncr_order` (
  `ncr_id` bigint(20) NOT NULL COMMENT 'NCR ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `ncr_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'NCR编号',
  `source_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源类型(IQC/IPQC/OQC/PROCESS/CUSTOMER)',
  `source_id` bigint(20) DEFAULT NULL COMMENT '来源单据ID(iqc_id/ipqc_id/oqc_id/step_record_id)',
  `wo_id` bigint(20) DEFAULT NULL COMMENT '关联工单ID',
  `wo_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单编号(冗余)',
  `card_id` bigint(20) DEFAULT NULL COMMENT '流转卡ID(PROCESS来源)',
  `step_record_id` bigint(20) DEFAULT NULL COMMENT '工序记录ID(PROCESS来源)',
  `process_id` bigint(20) DEFAULT NULL COMMENT '工序ID(IPQC/PROCESS来源)',
  `process_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序名称(冗余)',
  `material_id` bigint(20) DEFAULT NULL COMMENT '物料ID',
  `material_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料编码(冗余)',
  `material_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料名称(冗余)',
  `lot_id` bigint(20) DEFAULT NULL COMMENT '关联批次ID(隔离用)',
  `lot_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批次编码(冗余)',
  `defect_qty` decimal(14,4) NOT NULL COMMENT '不良数量',
  `disposition` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处置(REWORK/SCRAP/ACCEPT_AS_IS/RETURN)',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'OPEN' COMMENT 'OPEN/REVIEW/DISPOSITION/IN_REWORK/CLOSED',
  `review_by` bigint(20) DEFAULT NULL COMMENT '评审人',
  `review_time` datetime DEFAULT NULL COMMENT '评审时间',
  `disposition_by` bigint(20) DEFAULT NULL COMMENT '处置人',
  `disposition_time` datetime DEFAULT NULL COMMENT '处置时间',
  `disposition_signature_id` bigint(20) DEFAULT NULL COMMENT '处置签名ID(P0-6预留)',
  `created_time` datetime NOT NULL COMMENT '创建时间',
  `closed_time` datetime DEFAULT NULL COMMENT '关闭时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志(0正常 1删除)',
  PRIMARY KEY (`ncr_id`) USING BTREE,
  UNIQUE KEY `uk_ncr_code` (`tenant_id`,`ncr_code`) USING BTREE,
  UNIQUE KEY `uk_source` (`tenant_id`,`source_type`,`source_id`) USING BTREE,
  KEY `idx_wo_id` (`wo_id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_lot_id` (`lot_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='NCR不合格品单';

