DROP TABLE IF EXISTS `ncr_rework_order`;

CREATE TABLE `ncr_rework_order` (
  `rework_id` bigint(20) NOT NULL COMMENT '返工记录ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `rework_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '返工工单编号',
  `ncr_id` bigint(20) NOT NULL COMMENT '关联NCR ID',
  `original_wo_id` bigint(20) NOT NULL COMMENT '原工单ID',
  `original_wo_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原工单编号(冗余)',
  `rework_wo_id` bigint(20) NOT NULL COMMENT '生成的返工工单ID(pro_work_order.mes_wo_id)',
  `rework_wo_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '返工工单编号(冗余)',
  `rework_qty` decimal(14,4) NOT NULL COMMENT '返工数量',
  `rework_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '返工原因',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'OPEN' COMMENT 'OPEN/IN_PROGRESS/COMPLETED',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志(0正常 1删除)',
  PRIMARY KEY (`rework_id`) USING BTREE,
  UNIQUE KEY `uk_rework_code` (`tenant_id`,`rework_code`) USING BTREE,
  KEY `idx_ncr_id` (`ncr_id`) USING BTREE,
  KEY `idx_rework_wo_id` (`rework_wo_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='NCR返工工单';

DROP TABLE IF EXISTS `pro_andon`;

CREATE TABLE `pro_andon` (
  `andon_id` bigint(20) NOT NULL COMMENT '安灯ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `andon_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '安灯编号',
  `mes_wo_id` bigint(20) DEFAULT NULL COMMENT '关联MES工单ID',
  `wo_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单编号(冗余)',
  `card_id` bigint(20) DEFAULT NULL COMMENT '关联流转卡ID',
  `card_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流转卡编号(冗余)',
  `step_record_id` bigint(20) DEFAULT NULL COMMENT '关联流转卡工序记录ID',
  `station_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工位编码(设备通道呼叫)',
  `call_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '呼叫类型: QUALITY/MATERIAL/EQUIPMENT/OTHER',
  `call_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '呼叫原因',
  `andon_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'CALLED' COMMENT 'CALLED/RESPONDED/RESOLVED/CANCELLED',
  `caller_id` bigint(20) DEFAULT NULL COMMENT '呼叫人ID',
  `caller_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '呼叫人姓名',
  `responder_id` bigint(20) DEFAULT NULL COMMENT '响应人ID',
  `responder_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '响应人姓名',
  `call_time` datetime DEFAULT NULL COMMENT '呼叫时间',
  `respond_time` datetime DEFAULT NULL COMMENT '响应时间',
  `resolve_time` datetime DEFAULT NULL COMMENT '解决时间',
  `duration_minutes` int(11) DEFAULT NULL COMMENT '持续时长(分钟, 解决时计算)',
  `source` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'MANUAL' COMMENT 'MANUAL/IoT(来源)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notify_user_ids` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '呼叫通知被通知人ID(逗号分隔)',
  `notify_time` datetime DEFAULT NULL COMMENT '呼叫通知落库时间(非空=呼叫通知已发出,幂等依据)',
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  PRIMARY KEY (`andon_id`) USING BTREE,
  UNIQUE KEY `uk_andon_no` (`tenant_id`,`andon_no`) USING BTREE,
  KEY `idx_andon_status` (`andon_status`) USING BTREE,
  KEY `idx_call_type` (`call_type`) USING BTREE,
  KEY `idx_mes_wo_id` (`mes_wo_id`) USING BTREE,
  KEY `idx_card_id` (`card_id`) USING BTREE,
  KEY `idx_station_code` (`station_code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES安灯呼叫';

INSERT INTO `pro_andon` (`andon_id`, `tenant_id`, `andon_no`, `mes_wo_id`, `wo_no`, `card_id`, `card_no`, `step_record_id`, `station_code`, `call_type`, `call_reason`, `andon_status`, `caller_id`, `caller_name`, `responder_id`, `responder_name`, `call_time`, `respond_time`, `resolve_time`, `duration_minutes`, `source`, `remark`, `notify_user_ids`, `notify_time`, `create_dept`, `create_by`, `create_time`, `update_by`, `update_time`, `del_flag`) VALUES
(2104774462089936897, '000000', 'AND-20260929-1236', NULL, NULL, NULL, NULL, NULL, NULL, 'EQUIPMENT', 'IoT设备告警[TEMPERATURE]: 设备 DEV0025 属性 temperature 越限：当前 187.2 > 阈值 80.0000（规则：温度超上限(全局默认)） (值=187.2, 阈值=80.0000)', 'RESOLVED', NULL, NULL, 1, 'admin', '2026-09-29 11:25:11', '2026-09-29 13:23:39', '2026-09-29 13:23:39', 118, 'MANUAL', '复核DEV0025已入库温度187.3℃及产品规则8701（220℃）；规则7001错误低优先级匹配造成误报，现按人工关闭留痕；187.3℃高于80℃，不作为规则7001自动恢复证据。', '1', '2026-09-29 11:25:11', -1, -1, '2026-09-29 11:25:11', -1, '2026-09-29 11:25:11', '0'),
(2104804656011997186, '000000', 'AND-20260929-0028', NULL, NULL, NULL, NULL, NULL, NULL, 'EQUIPMENT', 'IoT设备告警[TEMPERATURE]: 设备 DEV0025 属性 temperature 越限：当前 224.8 > 阈值 220.0000（规则：注塑机料筒温度超上限） (值=224.8, 阈值=220.0000)', 'RESOLVED', NULL, NULL, 1, 'admin', '2026-09-29 13:25:10', '2026-09-29 13:28:17', '2026-09-29 13:28:17', 3, 'MANUAL', '设备DEV0025产品规则8701超温告警已自动恢复，入库恢复温度187.24℃；确认阈值220℃，按联动通知记录复核后关闭安灯。现有来源显示MANUAL为已记录待修复缺陷，不改写历史来源。', '1', '2026-09-29 13:25:10', -1, -1, '2026-09-29 13:25:10', -1, '2026-09-29 13:25:10', '0'),
(2104823418433994754, '000000', 'AND-20260929-3338', NULL, NULL, NULL, NULL, NULL, NULL, 'EQUIPMENT', 'IoT设备告警[TEMPERATURE] (deviceCode=DEV0025, deviceId=2104512194450214913): 设备 DEV0025 属性 temperature 越限：当前 224.8 > 阈值 220.0000（规则：注塑机料筒温度超上限） (值=224.8, 阈值=220.0000)', 'RESOLVED', NULL, NULL, 1, 'admin', '2026-09-29 14:39:43', '2026-09-29 14:41:58', '2026-09-29 14:41:58', 2, 'IoT', '设备DEV0025产品规则8701超温已由入库恢复值187.23℃自动恢复；经同源通知记录确认IoT安灯，复核关闭。', '1', '2026-09-29 14:39:43', -1, -1, '2026-09-29 14:39:43', -1, '2026-09-29 14:39:43', '0'),
(2105517750573047810, '000000', 'AND-20261001-5021', NULL, NULL, NULL, NULL, NULL, NULL, 'EQUIPMENT', 'IoT设备告警[TEMPERATURE] (deviceCode=DEV0025, deviceId=2104512194450214913, mesEquipmentId=1): 设备 DEV0025 属性 temperature 越限：当前 224.8 > 阈值 220.0000（规则：注塑机料筒温度超上限） (值=224.8, 阈值=220.0000)', 'RESOLVED', NULL, NULL, 1, 'admin', '2026-10-01 12:38:45', '2026-10-01 12:40:20', '2026-10-01 12:40:20', 1, 'IoT', '设备温度恢复正常，已核对同源IoT告警与通知记录后关闭安灯。', '1', '2026-10-01 12:38:45', -1, -1, '2026-10-01 12:38:45', -1, '2026-10-01 12:38:45', '0');

DROP TABLE IF EXISTS `pro_dispatch`;

CREATE TABLE `pro_dispatch` (
  `dispatch_id` bigint(20) NOT NULL COMMENT '派工单ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `dispatch_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '派工单编号',
  `mes_wo_id` bigint(20) NOT NULL COMMENT '关联MES工单ID',
  `wo_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单编号(冗余)',
  `card_id` bigint(20) DEFAULT NULL COMMENT '关联流转卡ID',
  `card_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流转卡编号(冗余)',
  `step_record_id` bigint(20) DEFAULT NULL COMMENT '关联流转卡工序记录ID',
  `sequence_num` int(11) DEFAULT NULL COMMENT '工序序号(冗余)',
  `process_id` bigint(20) NOT NULL COMMENT '工序ID',
  `process_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `process_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `workcenter_id` bigint(20) DEFAULT NULL,
  `workcenter_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `operator_id` bigint(20) DEFAULT NULL COMMENT '操作员ID(SchWorker.workerId)',
  `operator_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作员姓名',
  `planned_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '派工数量',
  `completed_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '已完成数量',
  `good_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '良品数量',
  `defect_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '不良品数量',
  `scrap_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '报废数量',
  `dispatch_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT 'PENDING/IN_PROGRESS/COMPLETED/CANCELLED',
  `plan_start_time` datetime DEFAULT NULL,
  `plan_end_time` datetime DEFAULT NULL,
  `actual_start_time` datetime DEFAULT NULL,
  `actual_end_time` datetime DEFAULT NULL,
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  PRIMARY KEY (`dispatch_id`) USING BTREE,
  UNIQUE KEY `uk_dispatch_no` (`tenant_id`,`dispatch_no`) USING BTREE,
  KEY `idx_mes_wo_id` (`mes_wo_id`) USING BTREE,
  KEY `idx_card_id` (`card_id`) USING BTREE,
  KEY `idx_step_record_id` (`step_record_id`) USING BTREE,
  KEY `idx_operator_id` (`operator_id`) USING BTREE,
  KEY `idx_dispatch_status` (`dispatch_status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES派工单';

