DROP TABLE IF EXISTS `pro_flow_card`;

CREATE TABLE `pro_flow_card` (
  `card_id` bigint(20) NOT NULL COMMENT '流转卡ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `card_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '流转卡编号',
  `mes_wo_id` bigint(20) NOT NULL COMMENT '关联MES工单ID',
  `wo_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工单编号(冗余)',
  `material_id` bigint(20) DEFAULT NULL COMMENT '物料ID',
  `material_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料编码(冗余)',
  `material_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料名称(冗余)',
  `planned_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '计划数量',
  `completed_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '已完成数量',
  `scrap_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '报废数量',
  `aggregated_flag` tinyint(4) NOT NULL DEFAULT '0' COMMENT '完工数量是否已一次性入账到工单(0=未入账 1=已入账)',
  `current_step_id` bigint(20) DEFAULT NULL COMMENT '当前工序步骤记录ID',
  `current_step_seq` int(4) DEFAULT NULL COMMENT '当前工序序号',
  `card_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'CREATED' COMMENT '流转卡状态: CREATED/RELEASED/IN_PROGRESS/COMPLETED/CLOSED',
  `barcode` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流转卡条码',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志(0正常 1删除)',
  PRIMARY KEY (`card_id`) USING BTREE,
  UNIQUE KEY `uk_card_no` (`tenant_id`,`card_no`) USING BTREE,
  UNIQUE KEY `uk_barcode` (`tenant_id`,`barcode`) USING BTREE,
  KEY `idx_mes_wo_id` (`mes_wo_id`) USING BTREE,
  KEY `idx_card_status` (`card_status`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES流转卡表';

