DROP TABLE IF EXISTS `pro_flow_card_step`;

CREATE TABLE `pro_flow_card_step` (
  `step_record_id` bigint(20) NOT NULL COMMENT '工序记录ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `card_id` bigint(20) NOT NULL COMMENT '关联流转卡ID',
  `card_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流转卡编号(冗余)',
  `mes_wo_id` bigint(20) NOT NULL COMMENT '关联MES工单ID(冗余便于查询)',
  `wo_step_id` bigint(20) DEFAULT NULL COMMENT '关联工单工序步骤ID(pro_work_order_step.step_id)',
  `sequence_num` int(4) NOT NULL DEFAULT '0' COMMENT '工序序号(从1开始)',
  `process_id` bigint(20) DEFAULT NULL COMMENT '工序ID(来自ERP bd_routing_step)',
  `process_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序编码(冗余)',
  `process_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序名称(冗余)',
  `workcenter_id` bigint(20) DEFAULT NULL COMMENT '工作中心ID',
  `workcenter_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工作中心编码(冗余)',
  `is_key_process` tinyint(1) DEFAULT '0' COMMENT '是否关键工序(0否 1是)',
  `step_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT '工序状态: PENDING/IN_PROGRESS/COMPLETED/SKIPPED',
  `operator_id` bigint(20) DEFAULT NULL COMMENT '操作员ID',
  `operator_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作员姓名(冗余)',
  `planned_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '计划数量',
  `good_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '良品数量',
  `defect_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '不良品数量',
  `scrap_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '报废数量',
  `actual_start_time` datetime DEFAULT NULL COMMENT '实际开始时间',
  `actual_end_time` datetime DEFAULT NULL COMMENT '实际结束时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `entry_check_result` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '进站校验结果(PASS/FAIL)',
  `entry_check_remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '进站校验备注(失败原因)',
  `exit_check_result` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '出站校验结果(PASS/FAIL)',
  `exit_check_remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '出站校验备注(失败原因)',
  `skip_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '跳站原因',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志(0正常 1删除)',
  PRIMARY KEY (`step_record_id`) USING BTREE,
  KEY `idx_card_id` (`card_id`) USING BTREE,
  KEY `idx_mes_wo_id` (`mes_wo_id`) USING BTREE,
  KEY `idx_step_status` (`step_status`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES流转卡工序记录表';

