DROP TABLE IF EXISTS `pro_step_check_rule`;

CREATE TABLE `pro_step_check_rule` (
  `rule_id` bigint(20) NOT NULL COMMENT '规则ID(主键)',
  `tenant_id` varchar(20) NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `process_id` bigint(20) NOT NULL COMMENT '工序ID',
  `check_type` varchar(32) NOT NULL COMMENT '校验类型',
  `check_stage` varchar(16) NOT NULL COMMENT '校验阶段: ENTRY/EXIT',
  `enabled` char(1) DEFAULT '1' COMMENT '是否启用(0停用 1启用)',
  `error_msg` varchar(200) DEFAULT NULL COMMENT '校验失败提示',
  `sort_order` int(4) DEFAULT '0' COMMENT '排序',
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`rule_id`) USING BTREE,
  KEY `idx_process_id` (`process_id`) USING BTREE,
  KEY `idx_check_stage` (`check_stage`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='MES工序校验规则配置';

DROP TABLE IF EXISTS `pro_step_guide`;

CREATE TABLE `pro_step_guide` (
  `guide_id` bigint(20) NOT NULL COMMENT '指引ID(主键)',
  `tenant_id` varchar(20) NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `process_id` bigint(20) NOT NULL COMMENT '工序ID(ERP bd_process.process_id)',
  `guide_type` varchar(16) NOT NULL COMMENT '指引类型: TEXT/SOP_LINK',
  `guide_title` varchar(128) DEFAULT NULL COMMENT '指引标题',
  `guide_content` text COMMENT '文本内容(TEXT类型用)',
  `sop_id` bigint(20) DEFAULT NULL COMMENT '关联SOP文档(SOP_LINK类型用)',
  `sort_order` int(4) DEFAULT '0' COMMENT '排序',
  `enabled` char(1) DEFAULT '1' COMMENT '是否启用(0停用 1启用)',
  `create_dept` bigint(20) DEFAULT NULL,
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`guide_id`) USING BTREE,
  KEY `idx_process_id` (`process_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='MES工序流程指引配置';

DROP TABLE IF EXISTS `pro_work_order`;

CREATE TABLE `pro_work_order` (
  `mes_wo_id` bigint(20) NOT NULL COMMENT 'MES工单ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `erp_wo_id` bigint(20) DEFAULT NULL COMMENT '关联ERP工单ID',
  `wo_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'MES工单编号(继承或派生)',
  `material_id` bigint(20) DEFAULT NULL COMMENT '产品物料ID',
  `material_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品编码(冗余)',
  `material_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品名称(冗余)',
  `planned_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '计划数量',
  `completed_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '已完成数量',
  `scrap_qty` decimal(18,4) DEFAULT '0.0000' COMMENT '报废数量',
  `unit_id` bigint(20) DEFAULT NULL COMMENT '单位ID',
  `unit_name` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位名称',
  `plan_start_date` datetime DEFAULT NULL COMMENT '计划开工日期',
  `plan_end_date` datetime DEFAULT NULL COMMENT '计划完工日期',
  `actual_start_date` datetime DEFAULT NULL COMMENT '实际开工时间',
  `actual_end_date` datetime DEFAULT NULL COMMENT '实际完工时间',
  `workshop_id` bigint(20) DEFAULT NULL COMMENT '车间ID',
  `workshop_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '车间名称(冗余)',
  `bom_id` bigint(20) DEFAULT NULL COMMENT 'BOM ID',
  `equipment_id` bigint(20) DEFAULT NULL COMMENT '关联设备ID',
  `routing_id` bigint(20) DEFAULT NULL COMMENT '工艺路线ID(MES侧维护)',
  `wo_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'CREATED' COMMENT '工单状态: CREATED/RELEASED/IN_PROGRESS/COMPLETED/CANCELLED',
  `priority` int(4) DEFAULT '5' COMMENT '优先级(1最高,9最低)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `select_flow_id` bigint(20) DEFAULT NULL COMMENT '已选审批流程模板ID',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志(0正常 1删除)',
  `source_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'ERP' COMMENT '工单来源(ERP/REWORK/MANUAL)',
  `release_package_id` bigint(20) DEFAULT NULL COMMENT '发布包ID(mes_release_package, 工单按此包生成)',
  `release_package_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发布包编码(冗余)',
  `release_package_ver` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发布包版本(冗余快照)',
  `release_config` text COLLATE utf8mb4_unicode_ci COMMENT '发布包配置项快照(JSON数组, 供工位/报表消费)',
  PRIMARY KEY (`mes_wo_id`) USING BTREE,
  UNIQUE KEY `uk_wo_no` (`tenant_id`,`wo_no`) USING BTREE,
  UNIQUE KEY `uk_tenant_erp_wo` (`tenant_id`,`erp_wo_id`) USING BTREE,
  KEY `idx_erp_wo_id` (`erp_wo_id`) USING BTREE,
  KEY `idx_material_id` (`material_id`) USING BTREE,
  KEY `idx_wo_status` (`wo_status`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE,
  KEY `idx_equipment_id` (`equipment_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES工单表';

