DROP TABLE IF EXISTS `pro_work_order_bom_line`;

CREATE TABLE `pro_work_order_bom_line` (
  `wo_bom_line_id` bigint(20) NOT NULL COMMENT '快照明细ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `mes_wo_id` bigint(20) NOT NULL COMMENT '关联MES工单ID',
  `mbom_line_id` bigint(20) DEFAULT NULL COMMENT '源mes_mbom_line.mbom_line_id(可空,无MBOM时)',
  `bom_id` bigint(20) DEFAULT NULL COMMENT 'ERP BOM ID',
  `bom_detail_id` bigint(20) DEFAULT NULL COMMENT 'ERP明细ID(溯源)',
  `child_material_id` bigint(20) NOT NULL COMMENT '子项物料ID',
  `child_material_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料编码(冗余)',
  `child_material_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料名称(冗余)',
  `quantity_per_parent` decimal(18,6) NOT NULL COMMENT '单位父项用量',
  `loss_rate` decimal(8,4) DEFAULT '0.0000' COMMENT '损耗率(%)',
  `total_quantity` decimal(18,6) DEFAULT NULL COMMENT '含损耗用量 = qty × (1 + loss/100)',
  `routing_step_id` bigint(20) DEFAULT NULL COMMENT '工序步骤ID',
  `sequence_num` int(11) DEFAULT NULL COMMENT '工序序号(冗余)',
  `process_id` bigint(20) DEFAULT NULL COMMENT '工序ID',
  `process_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序编码(冗余)',
  `process_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序名称(冗余)',
  `workstation_id` bigint(20) DEFAULT NULL COMMENT '工位ID',
  `workstation_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工位编码(冗余)',
  `workstation_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工位名称(冗余)',
  `operation_content` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '作业内容',
  `backflush_flag` tinyint(1) DEFAULT '0' COMMENT '是否倒冲 0否1是',
  `sort_order` int(11) DEFAULT '0' COMMENT '显示排序',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`wo_bom_line_id`) USING BTREE,
  KEY `idx_mes_wo_id` (`mes_wo_id`) USING BTREE,
  KEY `idx_child_material_id` (`child_material_id`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES工单BOM明细快照';

