DROP TABLE IF EXISTS `qc_inspect_detail`;

CREATE TABLE `qc_inspect_detail` (
  `detail_id` bigint(20) NOT NULL COMMENT '检验明细ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `check_id` bigint(20) NOT NULL COMMENT '检验单ID(qc_iqc.iqc_id/qc_ipqc.ipqc_id/qc_oqc.oqc_id)',
  `check_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验类别: IQC/IPQC/OQC',
  `template_id` bigint(20) DEFAULT NULL COMMENT '来源模板ID(快照溯源)',
  `item_id` bigint(20) DEFAULT NULL COMMENT '来源检验项目ID',
  `item_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目编码(快照)',
  `item_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目名称(快照)',
  `data_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'QUANTITATIVE' COMMENT '数据类型(快照): QUANTITATIVE/QUALITATIVE',
  `standard_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标准类型(快照): NOMINAL/LSL_ONLY/USL_ONLY/LSL_USL',
  `standard_desc` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标准快照描述(如10±0.05mm)',
  `unit` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位(快照)',
  `criticality` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'MAJOR' COMMENT '关键度(快照): CRITICAL/MAJOR/MINOR',
  `sample_qty` decimal(14,4) DEFAULT NULL COMMENT '样本量',
  `measured_value` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实测值(定量:数值/多值; 定性:OK/NG等)',
  `nominal_value` decimal(18,6) DEFAULT NULL COMMENT '名义值(快照, 判定用)',
  `lsl_value` decimal(18,6) DEFAULT NULL COMMENT '下限(快照, 判定用)',
  `usl_value` decimal(18,6) DEFAULT NULL COMMENT '上限(快照, 判定用)',
  `tol_upper` decimal(18,6) DEFAULT NULL COMMENT '上公差(快照, 判定用)',
  `tol_lower` decimal(18,6) DEFAULT NULL COMMENT '下公差(快照, 判定用)',
  `judge_result` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT '判定结果: PASS/FAIL/PENDING',
  `seq_num` int(11) DEFAULT '1' COMMENT '序号',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`detail_id`) USING BTREE,
  KEY `idx_check` (`check_type`,`check_id`) USING BTREE,
  KEY `idx_check_id` (`check_id`) USING BTREE,
  KEY `idx_tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='QC检验单明细';

