DROP TABLE IF EXISTS `qc_inspect_item`;

CREATE TABLE `qc_inspect_item` (
  `item_id` bigint(20) NOT NULL COMMENT '检验项目ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `template_id` bigint(20) NOT NULL COMMENT '关联qc_inspect_template.template_id',
  `item_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目编码',
  `item_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目名称',
  `data_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'QUANTITATIVE' COMMENT '数据类型: QUANTITATIVE定量/QUALITATIVE定性',
  `unit` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '计量单位',
  `standard_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标准类型: NOMINAL名义值/LSL_ONLY/USL_ONLY/LSL_USL',
  `nominal_value` decimal(18,6) DEFAULT NULL COMMENT '名义值(NOMINAL用)',
  `lsl_value` decimal(18,6) DEFAULT NULL COMMENT '下规格限LSL',
  `usl_value` decimal(18,6) DEFAULT NULL COMMENT '上规格限USL',
  `tol_upper` decimal(18,6) DEFAULT NULL COMMENT '上公差(NOMINAL用, 名义+tolUpper)',
  `tol_lower` decimal(18,6) DEFAULT NULL COMMENT '下公差(NOMINAL用, 名义-tolLower)',
  `aql_level` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验水平(如II)',
  `sample_plan_code` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '抽样方案(如AQL1.0)',
  `criticality` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'MAJOR' COMMENT '关键度: CRITICAL关键(一票否决)/MAJOR/MINOR',
  `seq_num` int(11) DEFAULT '1' COMMENT '序号',
  `enabled` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '是否启用 1是0否',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
