DROP TABLE IF EXISTS `qc_oqc`;

CREATE TABLE `qc_oqc` (
  `oqc_id` bigint(20) NOT NULL COMMENT 'OQC ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `oqc_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'OQC编号',
  `so_id` bigint(20) DEFAULT NULL COMMENT 'ERP销售订单ID',
  `material_id` bigint(20) NOT NULL COMMENT '物料ID',
  `material_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料编码(冗余)',
  `material_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料名称(冗余)',
  `quantity` decimal(14,4) NOT NULL COMMENT '检验数量',
  `sample_qty` decimal(14,4) DEFAULT NULL COMMENT '抽样数量',
  `inspect_result` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT '检验结果: QUALIFIED/UNQUALIFIED/PENDING',
  `defect_info` json DEFAULT NULL COMMENT '不良品信息(类型/数量/描述)',
  `inspector_id` bigint(20) DEFAULT NULL COMMENT '检验员ID',
  `inspector_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验员姓名',
  `inspect_time` datetime DEFAULT NULL COMMENT '检验时间',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT '状态: PENDING/INSPECTING/COMPLETED',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  `photo_oss_ids` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验照片附件ossId串(逗号分隔)',
  PRIMARY KEY (`oqc_id`) USING BTREE,
  UNIQUE KEY `uk_oqc_no` (`tenant_id`,`oqc_no`) USING BTREE,
  UNIQUE KEY `uk_oqc_so_material` (`tenant_id`,`so_id`,`material_id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_so_id` (`so_id`) USING BTREE,
  KEY `idx_material_id` (`material_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES出货检验';

