DROP TABLE IF EXISTS `sop_process_binding`;

CREATE TABLE `sop_process_binding` (
  `binding_id` bigint(20) NOT NULL COMMENT '绑定ID(主键)',
  `tenant_id` varchar(20) NOT NULL DEFAULT '000000',
  `process_id` bigint(20) NOT NULL COMMENT '工序ID(ERP bd_process.process_id, 工序主数据PK)',
  `process_code` varchar(64) DEFAULT NULL COMMENT '工序编码(冗余)',
  `process_name` varchar(128) DEFAULT NULL COMMENT '工序名称(冗余)',
  `process_category` varchar(16) DEFAULT NULL COMMENT '工序类别(冗余, PROCESSING/ASSEMBLY/INSPECTION/PACKAGING)',
  `sop_id` bigint(20) NOT NULL COMMENT 'SOP ID',
  `version_no` varchar(32) DEFAULT NULL COMMENT '指定版本号(空=当前发布版)',
  `is_default` char(1) DEFAULT '0' COMMENT '是否该工序默认SOP(1/0)',
  `sort_order` int(11) DEFAULT '0' COMMENT '排序',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`binding_id`) USING BTREE,
  KEY `idx_process` (`process_id`) USING BTREE,
