DROP TABLE IF EXISTS `sop_version`;

CREATE TABLE `sop_version` (
  `version_id` bigint(20) NOT NULL COMMENT '版本ID(主键)',
  `tenant_id` varchar(20) NOT NULL DEFAULT '000000',
  `sop_id` bigint(20) NOT NULL COMMENT 'SOP ID',
  `version_no` varchar(32) NOT NULL COMMENT '版本号(如1.0/1.1)',
  `file_oss_id` bigint(20) NOT NULL COMMENT '该版本文件OSS ID',
  `file_type` varchar(16) DEFAULT NULL COMMENT '文件类型: PDF/IMAGE/VIDEO/WORD',
  `file_hash` varchar(64) DEFAULT NULL COMMENT '该版本正文的 SM3(签名绑定正文用), 空表示尚未计算',
  `change_log` varchar(500) DEFAULT NULL COMMENT '变更说明',
  `published_time` datetime DEFAULT NULL COMMENT '发布时间',
  `published_by` bigint(20) DEFAULT NULL COMMENT '发布人ID',
  `status` varchar(16) DEFAULT 'PENDING' COMMENT '状态: PENDING/CURRENT/HISTORICAL',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`version_id`) USING BTREE,
  UNIQUE KEY `uk_sop_version_no` (`sop_id`,`version_no`,`tenant_id`,`del_flag`) USING BTREE,
  KEY `idx_sop_id` (`sop_id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='SOP版本历史';

