DROP TABLE IF EXISTS `sop_view_log`;

CREATE TABLE `sop_view_log` (
  `log_id` bigint(20) NOT NULL COMMENT '查阅记录ID(主键)',
  `tenant_id` varchar(20) NOT NULL DEFAULT '000000',
  `sop_id` bigint(20) NOT NULL COMMENT 'SOP ID',
  `version_no` varchar(32) DEFAULT NULL COMMENT '查阅的版本号',
  `viewer_id` bigint(20) NOT NULL COMMENT '查阅人ID',
  `viewer_name` varchar(64) DEFAULT NULL COMMENT '查阅人姓名(冗余)',
  `view_time` datetime NOT NULL COMMENT '查阅时间',
  `wo_id` bigint(20) DEFAULT NULL COMMENT '关联工单ID',
  `wo_no` varchar(64) DEFAULT NULL COMMENT '工单编号(冗余)',
  `process_id` bigint(20) DEFAULT NULL COMMENT '关联工序ID',
  `process_name` varchar(128) DEFAULT NULL COMMENT '工序名称(冗余)',
  `workstation_id` bigint(20) DEFAULT NULL COMMENT '工位ID',
  `signature_id` bigint(20) DEFAULT NULL COMMENT '电子签名记录ID(预留,P0-6接入)',
  `ip_address` varchar(64) DEFAULT NULL COMMENT 'IP地址',
  `user_agent` varchar(256) DEFAULT NULL COMMENT 'User-Agent',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`log_id`) USING BTREE,
  KEY `idx_sop_id` (`sop_id`) USING BTREE,
  KEY `idx_viewer` (`viewer_id`) USING BTREE,
  KEY `idx_wo_id` (`wo_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='SOP查阅记录';

