DROP TABLE IF EXISTS `spc_control_chart`;

CREATE TABLE `spc_control_chart` (
  `chart_id` bigint(20) NOT NULL COMMENT '控制图ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `chart_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '控制图名称',
  `chart_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'X_BAR_R/X_BAR_S/P/C/U',
  `point_id` bigint(20) DEFAULT NULL COMMENT '关联采集点ID',
  `material_id` bigint(20) DEFAULT NULL COMMENT '关联物料ID',
  `process_id` bigint(20) DEFAULT NULL COMMENT '关联工序ID',
  `ucl` decimal(14,4) DEFAULT NULL COMMENT '上控制限(analyze计算回写)',
  `cl` decimal(14,4) DEFAULT NULL COMMENT '中心线',
  `lcl` decimal(14,4) DEFAULT NULL COMMENT '下控制限',
  `r_ucl` decimal(14,4) DEFAULT NULL COMMENT '次级图(R/S/MR)上控制限',
  `r_cl` decimal(14,4) DEFAULT NULL COMMENT '次级图(R/S/MR)中心线',
  `r_lcl` decimal(14,4) DEFAULT NULL COMMENT '次级图(R/S/MR)下控制限',
  `usl` decimal(14,4) DEFAULT NULL COMMENT '规格上限(USL, 用户维护)',
  `lsl` decimal(14,4) DEFAULT NULL COMMENT '规格下限(LSL, 用户维护)',
  `cp` decimal(10,4) DEFAULT NULL COMMENT '过程能力指数Cp(analyze回写)',
  `cpk` decimal(10,4) DEFAULT NULL COMMENT '过程能力指数Cpk(analyze回写)',
  `cpk_grade` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '能力等级: A+(>=1.67)/A(>=1.33)/B(>=1.0)/C(<1.0)',
  `pp` decimal(10,4) DEFAULT NULL COMMENT '过程性能指数Pp(长期)',
  `ppk` decimal(10,4) DEFAULT NULL COMMENT '过程性能指数Ppk(长期)',
  `sample_size` int(11) DEFAULT '5' COMMENT '样本大小',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVE' COMMENT 'ACTIVE/INACTIVE',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`chart_id`) USING BTREE,
  KEY `idx_point_id` (`point_id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES SPC控制图';

DROP TABLE IF EXISTS `spc_data_point`;

CREATE TABLE `spc_data_point` (
  `data_id` bigint(20) NOT NULL COMMENT '数据点ID(主键)',
  `tenant_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000',
  `chart_id` bigint(20) NOT NULL COMMENT '控制图ID',
  `sample_group` int(11) NOT NULL COMMENT '样本组号',
  `sample_index` int(11) DEFAULT NULL COMMENT '组内序号',
  `value` decimal(14,4) NOT NULL COMMENT '值(组均值/不良率/缺陷数等)',
  `sub_value` decimal(14,4) DEFAULT NULL COMMENT '组内离散度(R极差/S标准差/MR移动极差)',
  `is_ooc` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '是否超控制限(0/1)',
  `ooc_rule` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '违规规则(RULE1/2/3/4, 多规则逗号拼接)',
  `collect_time` datetime DEFAULT NULL COMMENT '采集时间',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`data_id`) USING BTREE,
  UNIQUE KEY `uk_chart_group` (`tenant_id`,`chart_id`,`sample_group`) USING BTREE,
  KEY `idx_chart_id` (`chart_id`) USING BTREE,
  KEY `idx_group` (`chart_id`,`sample_group`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='MES SPC数据点';

DROP TABLE IF EXISTS `tg_maintenance_plan`;

CREATE TABLE `tg_maintenance_plan` (
  `plan_id` bigint(20) NOT NULL COMMENT '计划ID(主键)',
  `tenant_id` varchar(20) NOT NULL DEFAULT '000000',
  `tooling_id` bigint(20) NOT NULL COMMENT '工装ID',
  `plan_name` varchar(128) NOT NULL COMMENT '计划名称',
  `trigger_type` varchar(16) NOT NULL COMMENT '触发类型: BY_COUNT/BY_HOURS/PERIODIC',
  `trigger_value` int(11) DEFAULT NULL COMMENT '触发阈值(次数/小时/天数)',
  `last_maintain_time` datetime DEFAULT NULL COMMENT '上次保养时间',
  `next_maintain_time` datetime DEFAULT NULL COMMENT '下次保养时间(PERIODIC)',
  `next_maintain_count` int(11) DEFAULT NULL COMMENT '下次保养次数阈值(BY_COUNT)',
  `next_maintain_hours` decimal(14,2) DEFAULT NULL COMMENT '下次保养时长阈值(BY_HOURS)',
  `enabled` char(1) DEFAULT '1' COMMENT '是否启用(1/0)',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`plan_id`) USING BTREE,
  UNIQUE KEY `uk_tooling_trigger` (`tooling_id`,`trigger_type`,`tenant_id`,`del_flag`) USING BTREE,
  KEY `idx_tooling_id` (`tooling_id`) USING BTREE,
  KEY `idx_enabled` (`enabled`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='MES工装保养计划';

