DROP TABLE IF EXISTS `tg_maintenance_record`;

CREATE TABLE `tg_maintenance_record` (
  `record_id` bigint(20) NOT NULL COMMENT '记录ID(主键)',
  `tenant_id` varchar(20) NOT NULL DEFAULT '000000',
