  `maintain_time` datetime NOT NULL COMMENT '保养时间',
  `maintainer_id` bigint(20) DEFAULT NULL COMMENT '保养人ID',
  `maintainer_name` varchar(64) DEFAULT NULL COMMENT '保养人姓名(冗余)',
  `used_count_before` int(11) DEFAULT NULL COMMENT '保养前次数',
  `used_count_after` int(11) DEFAULT NULL COMMENT '保养后次数(归零=0)',
  `used_hours_before` decimal(14,2) DEFAULT NULL COMMENT '保养前时长',
  `used_hours_after` decimal(14,2) DEFAULT NULL COMMENT '保养后时长(归零=0)',
  `description` varchar(500) DEFAULT NULL COMMENT '保养内容',
  `cost` decimal(14,2) DEFAULT NULL COMMENT '保养成本',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
