DROP TABLE IF EXISTS `tg_tooling`;

CREATE TABLE `tg_tooling` (
  `tooling_id` bigint(20) NOT NULL COMMENT '工装ID(主键)',
  `tenant_id` varchar(20) NOT NULL DEFAULT '000000',
