  `tooling_type` varchar(16) NOT NULL COMMENT '类型: MOLD/FIXTURE/CUTTER/GAUGE/OTHER',
  `spec` varchar(128) DEFAULT NULL COMMENT '规格',
  `workshop_id` bigint(20) DEFAULT NULL COMMENT '所属车间ID',
  `workshop_name` varchar(128) DEFAULT NULL COMMENT '车间名称(冗余)',
  `status` varchar(16) DEFAULT 'IDLE' COMMENT '状态: IDLE/IN_USE/CALIBRATING/MAINTENANCE/SCRAPPED',
  `total_life_count` int(11) DEFAULT NULL COMMENT '总寿命(次数)',
  `total_life_hours` decimal(14,2) DEFAULT NULL COMMENT '总寿命(小时)',
