  `calibrated_by` bigint(20) DEFAULT NULL COMMENT '校准人ID',
  `calibration_result` varchar(16) DEFAULT NULL COMMENT '校准结果: PASS/FAIL/ADJUSTED',
  `calibration_remark` varchar(500) DEFAULT NULL COMMENT '校准备注',
  `purchase_date` date DEFAULT NULL COMMENT '采购日期',
  `purchase_cost` decimal(14,2) DEFAULT NULL COMMENT '采购成本',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`tooling_id`) USING BTREE,
  UNIQUE KEY `uk_tooling_code` (`tenant_id`,`tooling_code`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_type` (`tooling_type`) USING BTREE,
  KEY `idx_workshop` (`workshop_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='MES工装台账';

